import Foundation

/// Interface language: English base, French, German and Spanish (the languages of Victron's Assistants).
///
/// - App chrome: `L("English text")` looks the text up in `<lang>.lproj/Localizable.strings`.
/// - Catalog text (labels, items, help from VE Configure): `L10n.catalog(_:)` looks it up in
///   `catalog-strings.json` (`{lang: {english: translation}}`, generated by tools/l10n_catalog.py).
///
/// The language is the app's (`Bundle.main.preferredLocalizations`), or `--language xx` on the command line.
/// Outside the .app (swift run, snapshots) the tables are read from the source tree.
enum L10n {
    static let supported = ["en", "fr", "de", "es"]

    static let language: String = {
        let args = CommandLine.arguments
        if let i = args.firstIndex(of: "--language"), i + 1 < args.count, supported.contains(args[i + 1]) { return args[i + 1] }
        if Bundle.main.localizations.contains(where: { $0 != "en" && supported.contains($0) }),
           let first = Bundle.main.preferredLocalizations.first, supported.contains(first) {
            return first
        }
        // Bare executable: no .lproj next to it, follow the user's languages (honours -AppleLanguages).
        for l in Locale.preferredLanguages {
            let code = String(l.prefix(2)).lowercased()
            if supported.contains(code) { return code }
        }
        return "en"
    }()

    /// Source tree root, for runs outside the .app bundle.
    private static var sourceRoot: URL {
        URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
    }

    private static let inApp = Bundle.main.bundlePath.hasSuffix(".app")

    static let ui: [String: String] = {
        guard language != "en" else { return [:] }
        let url = Bundle.main.url(forResource: "Localizable", withExtension: "strings", subdirectory: nil, localization: language)
            ?? (inApp ? nil : sourceRoot.appendingPathComponent("Resources/\(language).lproj/Localizable.strings"))
        guard let url, let dict = NSDictionary(contentsOf: url) as? [String: String] else { return [:] }
        return dict
    }()

    static let catalogTable: [String: String] = {
        guard language != "en" else { return [:] }
        let url = Bundle.main.url(forResource: "catalog-strings", withExtension: "json")
            ?? (inApp ? nil : sourceRoot.appendingPathComponent("Sources/VEConfigure/Resources/catalog-strings.json"))
        guard let url, let data = try? Data(contentsOf: url),
              let all = try? JSONDecoder().decode([String: [String: String]].self, from: data) else { return [:] }
        return all[language] ?? [:]
    }()

    /// A catalog string as displayed: exact match, then its cleaned form; English when untranslated.
    static func catalog(_ s: String) -> String {
        guard !catalogTable.isEmpty, !s.isEmpty else { return s }
        if let t = catalogTable[s] { return t }
        let n = Catalog.cleanCaption(stripMarkup(s))
        return catalogTable[n] ?? s
    }

    static func catalog(_ s: String?) -> String? { s.map { catalog($0) } }
}

/// Localised app text. Format arguments use `String(format:)` placeholders (`%@`, `%d`, `%1$@`…).
func L(_ key: String) -> String { L10n.ui[key] ?? key }

func L(_ key: String, _ args: CVarArg...) -> String {
    String(format: L10n.ui[key] ?? key, locale: Locale(identifier: L10n.language), arguments: args)
}
